UNCHANGED = {
    "EWS Groep", "Employees", "with skills", "06 38 99 73 84",
    "info@ewsgroep.nl", "Industrieweg 14", "3846 BD Harderwijk",
    "© 2026 EWS Groep B.V.", "Benedict", "Basecamp Eco-resorts",
    "Morgan & Mees Amsterdam", "BMC Schoonmaak B.V.", ".", "/",
    *LANGUAGES.values(), "NL", "EN", "TR", "BG",
}


def translate(text, language):
    if language == "nl" or not text or text in UNCHANGED:
        return text
    if text.endswith(" | EWS Groep"):
        return translate(text.removesuffix(" | EWS Groep"), language) + " | EWS Groep"
    try:
        return COPY[text][("en", "tr", "bg").index(language)]
    except KeyError as error:
        raise ValueError(f"Missing {language} translation: {text!r}") from error
